SELECT count(*) AS total, count(*) FILTER (WHERE tu.operation IN ('read', 'search', 'fetch')) AS reads, count(*) FILTER (WHERE tu.operation = 'write') AS writes, count(*) FILTER (WHERE tu.tool_name = 'Bash') AS commands, count(*) FILTER (WHERE tu.tool_name = 'Bash' AND tr.is_error) AS failed_commands FROM tools.uses tu LEFT JOIN tools.results tr ON tr.tool_use_id = tu.id AND tr.created_at <= '2026-09-24 08:22:50.453555+00'::timestamptz WHERE tu.session_id = 1173418 AND tu.created_at <= '2026-09-24 08:22:50.453555+00'::timestamptz
